const update = $input.first()?.json ?? {};
const callback = update.callback_query ?? null;
const message = update.message ?? null;
const fromId = String(callback?.from?.id ?? message?.from?.id ?? '');
const chatId = String(callback?.message?.chat?.id ?? message?.chat?.id ?? '');
const allowedId = '6552428480';
if (fromId !== allowedId || chatId !== allowedId) return [];

let action = 'help';
let query = '';
const callbackData = String(callback?.data ?? '');
const categoryMatch = callbackData.match(/^cti:category:(malware|vulnerability|data_breach|threat_intelligence|other)$/);
if (categoryMatch) {
  action = 'category';
  query = categoryMatch[1];
} else if (callbackData === 'cti:menu') {
  action = 'menu';
} else if (!callback) {
  const text = String(message?.text ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
  const lower = text.toLocaleLowerCase('en-US');
  const categories = new Map([
    ['malware', 'malware'], ['zararlı yazılım', 'malware'],
    ['vulnerability', 'vulnerability'], ['vulnerabilities', 'vulnerability'], ['zafiyet', 'vulnerability'],
    ['data breach', 'data_breach'], ['data breaches', 'data_breach'], ['veri ihlali', 'data_breach'],
    ['threat intelligence', 'threat_intelligence'], ['tehdit istihbaratı', 'threat_intelligence'],
    ['other', 'other'], ['diğer', 'other']
  ]);
  if (lower === '/start' || lower === '/menu' || lower === 'menu') {
    action = 'menu';
  } else if (lower === '/help' || lower === 'help' || lower === 'yardım') {
    action = 'help';
  } else if (categories.has(lower)) {
    action = 'category';
    query = categories.get(lower);
  } else {
    query = lower.replace(/^\/search\s+/, '').trim();
    if (query.length >= 2 && query.length <= 60 && /^[\p{L}\p{N}\s._:/-]+$/u.test(query)) action = 'search';
  }
}
return [{ json: { action, query: query || null, chat_id: chatId, has_callback: Boolean(callback), callback_query_id: callback?.id ?? null } }];

const request = $('Authorize and Parse Request').item.json;
const payload = typeof $json.lookup_result === 'string' ? JSON.parse($json.lookup_result) : $json.lookup_result;
if (!payload || !Array.isArray(payload.articles)) throw new Error('Invalid CTI lookup response.');
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const categoryNames = { malware: 'Malware', vulnerability: 'Vulnerabilities', data_breach: 'Data Breaches', threat_intelligence: 'Threat Intelligence', other: 'Other' };
const severityNames = { critical: 'Critical', high: 'High', medium: 'Medium', low: 'Low', unknown: 'Unknown' };
let message;
if (payload.action === 'menu') {
  message = '<b>🛡️ CTI News Query</b>\n\nChoose a category below or send a keyword such as <code>ransomware</code>, <code>CVE-2026</code>, or <code>browser vulnerability</code>.\n\nOnly analyzed articles from the last 8 days are searched. No AI call is used.';
} else if (payload.action === 'help') {
  message = '<b>CTI bot commands</b>\n\n<code>/menu</code> — show categories\n<code>/search keyword</code> — search recent analyzed news\n\nYou can also send the keyword directly.';
} else {
  const label = payload.action === 'category' ? categoryNames[payload.query] : `Search: ${payload.query}`;
  message = `<b>🛡️ ${escapeHtml(label ?? 'CTI Results')}</b>\n`;
  if (payload.articles.length === 0) {
    message += '\nNo matching analyzed article was found in the last 8 days.';
  } else {
    for (let index = 0; index < payload.articles.length; index++) {
      const article = payload.articles[index];
      const title = escapeHtml(String(article.title ?? '').slice(0, 220));
      const summary = escapeHtml(String(article.summary_tr ?? '').replace(/\s+/g, ' ').slice(0, 520));
      const source = escapeHtml(String(article.source_name ?? '').slice(0, 100));
      const severity = escapeHtml(severityNames[article.severity] ?? 'Unknown');
      const url = escapeHtml(String(article.canonical_url ?? ''));
      const block = `\n\n<b>${index + 1}. ${title}</b>\n${severity} · ${source}\n${summary}\n${url}`;
      if (message.length + block.length > 3850) break;
      message += block;
    }
  }
}
return { json: { chat_id: request.chat_id, message } };
